-- AI/ML pathway ("Cipher Division") Act 3 -- "Mathematical Language" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. The world-ai-mathematical-language
-- row (world-ai-mathematical-language, act-ai-1) already exists from the
-- Arc I spine migration -- this file only adds the campaign/operations/
-- missions/dialogue/objectives/challenges/hints under it.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-mathematical-language', 'world-ai-mathematical-language', 'mathematical-language', '3A - Mathematical Language', 'The mathematical vocabulary underneath every model: scalars, vectors, matrices and tensors, dot products and matrix multiplication, and the calculus of slopes, derivatives and gradients that training actually runs on -- learned so Byte can finally run real numbers on a fragment of Echo''s parameters.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-mathematical-language-1', 'campaign-ai-mathematical-language', 'objects-of-computation', 'Objects of Computation', 'Scalars, vectors, matrices and tensors, and the two operations -- dot products and matrix multiplication -- every layer in a network is built from.', 1),
  ('operation-ai-mathematical-language-2', 'campaign-ai-mathematical-language', 'the-shape-of-change', 'The Shape of Change', 'Functions, slopes, derivatives, partial derivatives and gradients -- the calculus training actually runs on, aimed at a real slice of Echo''s parameters.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-mathematical-language-01', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-1', 'scalars', 'Scalars', 'A single number can describe a temperature, a score, or one weight inside Echo''s parameter file -- and it is where the language this Act needs actually starts.', 'beginner', ARRAY['maya','byte'], null, null, '{"type":"simulation","simulationId":"scalars-sim"}'::jsonb, '{"xp":90,"credits":20}'::jsonb, false, 1),
  ('mission-ai-mathematical-language-02', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-1', 'vectors', 'Vectors', 'One number was never going to be enough to describe a point in Echo''s parameter space -- an ordered list of them is where direction and position actually start.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"vectors-sim"}'::jsonb, '{"xp":100,"credits":20}'::jsonb, false, 2),
  ('mission-ai-mathematical-language-03', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-1', 'matrices', 'Matrices', 'Stack enough related vectors together and rows and columns start to matter as much as the numbers themselves -- which is exactly what a layer of Echo''s weights looks like.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"matrices-sim"}'::jsonb, '{"xp":100,"credits":20}'::jsonb, false, 3),
  ('mission-ai-mathematical-language-04', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-1', 'tensors', 'Tensors', 'Scalars, vectors and matrices turn out to be the first three cases of one bigger idea -- and Echo''s entire parameter file is stored as that bigger idea.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"tensors-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 4),
  ('mission-ai-mathematical-language-05', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-1', 'dot-products', 'Dot Products', 'Two vectors on their own do not say much about each other -- the dot product is the one number that measures how aligned they actually are.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"dot-product-sim"}'::jsonb, '{"xp":110,"credits":25}'::jsonb, false, 5),
  ('mission-ai-mathematical-language-06', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-1', 'matrix-multiplication', 'Matrix Multiplication', 'One layer feeding into the next is nothing more than matrix multiplication, chained -- rows dotted against columns, over and over, all the way through Echo''s network.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"matrix-multiplication-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 6),
  ('mission-ai-mathematical-language-07', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-2', 'functions', 'Functions', 'Every model, including whatever Echo actually is, boils down to one idea from an ordinary math class: a function that turns an input into an output.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"functions-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 7),
  ('mission-ai-mathematical-language-08', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-2', 'slopes', 'Slopes', 'Before calculus gets formal, the slope of a line already answers the only question that matters: for a given change in input, how much does the output actually move.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"slopes-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 8),
  ('mission-ai-mathematical-language-09', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-2', 'derivatives', 'Derivatives', 'A curve does not have one slope -- it has a different one at every point, and the derivative is the tool that finds it exactly.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"derivatives-sim"}'::jsonb, '{"xp":130,"credits":30}'::jsonb, false, 9),
  ('mission-ai-mathematical-language-10', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-2', 'partial-derivatives', 'Partial Derivatives', 'A model does not have one input, it has millions of parameters at once -- and a partial derivative is how you ask what just one of them is doing while the rest hold still.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"partial-derivatives-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 10),
  ('mission-ai-mathematical-language-11', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-2', 'gradients', 'Gradients', 'Collect every partial derivative of a function into one vector, and it points in exactly the direction the function increases fastest -- the single idea the entire Act has been building toward.', 'intermediate', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"gradients-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 11),
  ('mission-ai-mathematical-language-12', 'world-ai-mathematical-language', 'campaign-ai-mathematical-language', 'operation-ai-mathematical-language-2', 'find-the-direction', 'Find the Direction', 'Every object and every rate of change this Act taught, aimed at one small slice of Echo''s actual parameters -- to see which direction its gradients are actually pointing.', 'boss', ARRAY['maya','byte'], '{"requiredMissionIds":["mission-ai-mathematical-language-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"find-the-direction-boss-sim"}'::jsonb, '{"xp":450,"credits":95,"badgeIds":["gradient-navigator"],"skillXp":{"ml_mathematics":50,"ai_ml_fundamentals":15}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-mathematical-language-01', 1, 'maya', 'Containment is holding. Byte wants something more than logs now -- Byte wants to run real numbers on a fragment of Echo''s parameters, the actual weights, not a summary of them.'),
  ('mission-ai-mathematical-language-01', 2, 'byte', 'I pulled a slice of the parameter file. Sixty-four numbers, then six thousand more sitting behind those. "Add this number to that number" does not get us far when there are millions of thats.'),
  ('mission-ai-mathematical-language-01', 3, 'byte', 'Start at the bottom. A scalar is a single number: one value, no direction, no structure attached. A temperature, a probability, one weight in Echo''s file -- all scalars.'),
  ('mission-ai-mathematical-language-01', 4, 'maya', 'Simple will not stay simple for long. Every one of Echo''s millions of parameters starts life as a scalar. Learn to see one clearly before you look at millions of them at once.'),

  ('mission-ai-mathematical-language-02', 1, 'byte', 'A scalar alone cannot tell you where something is or which way it is pointing. For that you need more than one number, held together in order.'),
  ('mission-ai-mathematical-language-02', 2, 'byte', 'A vector is an ordered list of numbers: [x, y, z], where each position in the list has a specific meaning, and the order matters. Swap two entries and it is a different vector.'),
  ('mission-ai-mathematical-language-02', 3, 'byte', 'Echo''s parameter slice is not one number, it is thousands of them, arranged as vectors -- each one describing a direction and a magnitude inside a space with more dimensions than either of us can picture.'),

  ('mission-ai-mathematical-language-03', 1, 'byte', 'A vector is one ordered list. A matrix is a rectangular grid of numbers -- rows and columns both -- and its shape is written as rows by columns.'),
  ('mission-ai-mathematical-language-03', 2, 'byte', 'A single layer inside a neural network is usually stored as one matrix: each row a set of weights feeding one neuron, each column a connection coming from one input.'),
  ('mission-ai-mathematical-language-03', 3, 'byte', 'Get the shape wrong and nothing else works. A 3-by-4 matrix has 3 rows and 4 columns -- 12 numbers total, and that shape has to match whatever it multiplies against.'),

  ('mission-ai-mathematical-language-04', 1, 'byte', 'Here is the pattern underneath everything so far. A scalar is a 0-dimensional array of numbers. A vector is 1-dimensional. A matrix is 2-dimensional. A tensor is the general name for an array with any number of dimensions.'),
  ('mission-ai-mathematical-language-04', 2, 'byte', 'Echo''s parameter file is not one matrix, it is thousands of tensors of different shapes stacked together -- some 2-dimensional, some 3 or 4-dimensional, depending on the layer.'),
  ('mission-ai-mathematical-language-04', 3, 'byte', 'The word sounds bigger than the idea actually is. "Tensor" just means numbers arranged in a grid with however many dimensions the job needs. Scalars, vectors and matrices were tensors the entire time.'),

  ('mission-ai-mathematical-language-05', 1, 'byte', 'Now the first real operation. The dot product takes two vectors of the same length and combines them into a single scalar: multiply matching positions together, then add up every result.'),
  ('mission-ai-mathematical-language-05', 2, 'byte', '[1, 2, 3] dotted with [4, 5, 6] is (1x4) + (2x5) + (3x6) = 4 + 10 + 18 = 32. One number out of two vectors.'),
  ('mission-ai-mathematical-language-05', 3, 'byte', 'The size of that number says something real: a large positive dot product means the vectors point in a similar direction. Near zero means they are close to unrelated. Negative means they point opposite ways. That single number is going to matter a lot once we get to gradients.'),

  ('mission-ai-mathematical-language-06', 1, 'byte', 'Matrix multiplication is dot products, scaled up. Multiply an m-by-n matrix by an n-by-p matrix, and each entry in the result is the dot product of one row from the first and one column from the second.'),
  ('mission-ai-mathematical-language-06', 2, 'byte', 'The shapes have to line up: the number of columns in the first matrix must equal the number of rows in the second. Get that wrong and the operation is not even defined.'),
  ('mission-ai-mathematical-language-06', 3, 'byte', 'Every forward pass through a network is exactly this, repeated per layer: an input vector, multiplied by a weight matrix, producing the next layer''s input. Echo does this thousands of times per response.'),

  ('mission-ai-mathematical-language-07', 1, 'byte', 'Objects handled. Now the shape of change, starting with the oldest idea in the batch: a function. Give it an input, it gives back exactly one output, following some fixed rule.'),
  ('mission-ai-mathematical-language-07', 2, 'byte', 'f(x) = 2x + 3 is a function. Feed it 5, it always returns 13. Feed it 5 again tomorrow, still 13. A model is the same idea, just with millions of parameters baked into the rule instead of two.'),
  ('mission-ai-mathematical-language-07', 3, 'byte', 'The part we actually care about is how the output changes when the input changes. That question -- how much, and in which direction -- is where the rest of this Act is headed.'),

  ('mission-ai-mathematical-language-08', 1, 'byte', 'The slope of a line is rise over run: how much the output changes, divided by how much the input changed to cause it.'),
  ('mission-ai-mathematical-language-08', 2, 'byte', 'A slope of 2 means every 1-unit increase in input produces a 2-unit increase in output. A slope of 0 means the output does not move at all, no matter what the input does. A negative slope means the output moves the opposite way.'),
  ('mission-ai-mathematical-language-08', 3, 'byte', 'Straight lines are the easy case. Nothing Echo computes is a straight line, but every curve still has a slope at any given point -- we just need a better way to find it than rise over run.'),

  ('mission-ai-mathematical-language-09', 1, 'byte', 'A straight line has one slope everywhere. A curve does not -- its steepness changes as you move along it. The derivative is the slope of the curve at one exact point, found by shrinking the "run" toward zero.'),
  ('mission-ai-mathematical-language-09', 2, 'byte', 'Formally, the derivative of f at x is the limit of the slope between x and a point infinitesimally close to it. In practice, for the functions we care about, there are rules: the derivative of x squared is 2x, of x cubed is 3x squared, and so on.'),
  ('mission-ai-mathematical-language-09', 3, 'byte', 'The derivative tells you two things at once, at that exact point: which direction the function is currently heading, and how steeply. Training a model is, underneath everything, following derivatives downhill.'),

  ('mission-ai-mathematical-language-10', 1, 'byte', 'Every derivative so far assumed one input variable. Echo''s parameter slice has thousands, all changing at once. A partial derivative asks the question for exactly one of them: how does the output change with respect to this one variable, treating every other variable as a fixed constant?'),
  ('mission-ai-mathematical-language-10', 2, 'byte', 'Notation-wise it looks like an ordinary derivative with a curled d: the partial derivative of f with respect to x, holding y constant. The math is identical to before -- just freeze every other variable first.'),
  ('mission-ai-mathematical-language-10', 3, 'byte', 'For f(x, y) = x squared + 3y, the partial with respect to x is 2x, treating y as a constant that disappears. The partial with respect to y is just 3, since x drops out entirely.'),

  ('mission-ai-mathematical-language-11', 1, 'byte', 'Here is where every piece from this Act meets. The gradient of a function with several variables is a vector: one entry per variable, and each entry is the partial derivative with respect to that variable.'),
  ('mission-ai-mathematical-language-11', 2, 'byte', 'For f(x, y) = x squared + y squared, the gradient is the vector (2x, 2y) -- the partial with respect to x in the first slot, the partial with respect to y in the second.'),
  ('mission-ai-mathematical-language-11', 3, 'byte', 'The gradient vector has a genuinely useful property: it points in the direction the function increases fastest, at that exact point. Training flips the sign and walks the opposite way, downhill, toward less error. That vector is exactly what we are about to go looking for in Echo''s parameters.'),

  ('mission-ai-mathematical-language-12', 1, 'maya', 'Scalars to gradients, all of it, aimed at something real now. Byte pulled a small slice of Echo''s parameter space and actually ran the numbers.'),
  ('mission-ai-mathematical-language-12', 2, 'byte', 'Three parameters, sampled at three checkpoints while Echo kept running. I computed the gradient vector at each one, the same way we just practiced. Cipher Division needs your read on what it shows before Maya signs off on anything.'),
  ('mission-ai-mathematical-language-12', 3, 'maya', 'A normally-trained model, finished training, has gradients that settle near zero -- the function has flattened out, nothing left to climb toward. That is the baseline. Tell me if Echo matches it.'),
  ('mission-ai-mathematical-language-12', 4, 'byte', 'It does not match it. Every reading ahead of you points the same way: directions that keep reversing, magnitudes that refuse to shrink.'),
  ('mission-ai-mathematical-language-12', 5, 'maya', 'Numbers do not explain why, only what -- and what is actually happening is a set of gradients that never settle, the way a finished model''s would. That is as far as the numbers alone can take us. The next question is whether what looks like a pattern in them actually is one, or just noise dressed up as one.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-mathematical-language-01-o1', 'mission-ai-mathematical-language-01', 1, 'Recognize a scalar', 'Sort each quantity into scalar or not-scalar.'),

  ('mission-ai-mathematical-language-02-o1', 'mission-ai-mathematical-language-02', 1, 'Define a vector', 'Choose the accurate definition of a vector.'),
  ('mission-ai-mathematical-language-02-o2', 'mission-ai-mathematical-language-02', 2, 'Read vector length', 'Match each vector to its dimension.'),

  ('mission-ai-mathematical-language-03-o1', 'mission-ai-mathematical-language-03', 1, 'Read the shape', 'State the shape of a matrix correctly, rows before columns.'),
  ('mission-ai-mathematical-language-03-o2', 'mission-ai-mathematical-language-03', 2, 'Count the entries', 'Count how many individual numbers a matrix contains.'),

  ('mission-ai-mathematical-language-04-o1', 'mission-ai-mathematical-language-04', 1, 'Place them on the ladder', 'Place scalars, vectors, matrices and tensors on the same dimensional ladder.'),
  ('mission-ai-mathematical-language-04-o2', 'mission-ai-mathematical-language-04', 2, 'Confirm the general case', 'Confirm how tensors relate to scalars, vectors and matrices.'),

  ('mission-ai-mathematical-language-05-o1', 'mission-ai-mathematical-language-05', 1, 'Compute a dot product', 'Compute a dot product by hand.'),
  ('mission-ai-mathematical-language-05-o2', 'mission-ai-mathematical-language-05', 2, 'Read what the result means', 'Read what the sign and size of a dot product actually mean.'),

  ('mission-ai-mathematical-language-06-o1', 'mission-ai-mathematical-language-06', 1, 'Check the shapes', 'Check whether two matrix shapes can be multiplied, and predict the result.'),
  ('mission-ai-mathematical-language-06-o2', 'mission-ai-mathematical-language-06', 2, 'Spot the invalid case', 'Sort matrix shape pairs into valid or invalid for multiplication.'),

  ('mission-ai-mathematical-language-07-o1', 'mission-ai-mathematical-language-07', 1, 'Confirm it is a function', 'Confirm what makes a rule a function.'),
  ('mission-ai-mathematical-language-07-o2', 'mission-ai-mathematical-language-07', 2, 'Evaluate one', 'Evaluate a function at a given input.'),

  ('mission-ai-mathematical-language-08-o1', 'mission-ai-mathematical-language-08', 1, 'Compute a slope', 'Compute the slope between two points.'),
  ('mission-ai-mathematical-language-08-o2', 'mission-ai-mathematical-language-08', 2, 'Read the sign', 'Read what the sign of a slope means.'),

  ('mission-ai-mathematical-language-09-o1', 'mission-ai-mathematical-language-09', 1, 'Apply the power rule', 'Apply the power rule to find a derivative.'),
  ('mission-ai-mathematical-language-09-o2', 'mission-ai-mathematical-language-09', 2, 'Read what it tells you', 'Read what the value of a derivative says about a function.'),

  ('mission-ai-mathematical-language-10-o1', 'mission-ai-mathematical-language-10', 1, 'Freeze the right variable', 'Take a partial derivative with respect to one variable.'),
  ('mission-ai-mathematical-language-10-o2', 'mission-ai-mathematical-language-10', 2, 'Confirm the other one', 'Take the partial derivative with respect to the other variable.'),

  ('mission-ai-mathematical-language-11-o1', 'mission-ai-mathematical-language-11', 1, 'Assemble a gradient', 'Order the steps of assembling a gradient vector.'),

  ('mission-ai-mathematical-language-12-o1', 'mission-ai-mathematical-language-12', 1, 'Read one gradient', 'Judge what a gradient vector that reverses direction actually indicates.'),
  ('mission-ai-mathematical-language-12-o2', 'mission-ai-mathematical-language-12', 2, 'Track the magnitude', 'Find the evidence that Echo''s sampled gradient is not settling toward zero.'),
  ('mission-ai-mathematical-language-12-o3', 'mission-ai-mathematical-language-12', 3, 'Rule out the ordinary explanation', 'Rule out ordinary, still-training as the explanation.'),
  ('mission-ai-mathematical-language-12-o4', 'mission-ai-mathematical-language-12', 4, 'State the finding', 'Having judged all three, state what Cipher Division actually found.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-mathematical-language-01-o1-c1', 'mission-ai-mathematical-language-01-o1', 1, 'drag_and_drop', 'Sort each quantity into scalar or not-scalar.', '{"items":[{"id":"i1","text":"A single weight value: 0.73"},{"id":"i2","text":"A list of three coordinates: [2, -1, 4]"},{"id":"i3","text":"Echo''s current temperature reading: 41.2"},{"id":"i4","text":"A 3x3 grid of numbers"},{"id":"i5","text":"The probability Echo assigns to one prediction: 0.86"}],"targets":[{"id":"t1","label":"Scalar"},{"id":"t2","label":"Not a scalar"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2","i5":"t1"}}'::jsonb),

  ('mission-ai-mathematical-language-02-o1-c1', 'mission-ai-mathematical-language-02-o1', 1, 'multiple_choice', 'A vector is best described as...', '{"question":"A vector is best described as...","options":[{"id":"a","text":"Any list of numbers, where order does not matter"},{"id":"b","text":"An ordered list of numbers, where position and order both carry meaning"},{"id":"c","text":"A single measurement with no structure"},{"id":"d","text":"A grid arranged in rows and columns"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-02-o2-c1', 'mission-ai-mathematical-language-02-o2', 1, 'drag_and_drop', 'Match each vector to its dimension (length).', '{"items":[{"id":"i1","text":"[4, -2]"},{"id":"i2","text":"[1, 0, 3]"},{"id":"i3","text":"[7]"},{"id":"i4","text":"[2, 2, 2, 2, 2]"}],"targets":[{"id":"t1","label":"1 dimension"},{"id":"t2","label":"2 dimensions"},{"id":"t3","label":"3 dimensions"},{"id":"t4","label":"5 dimensions"}]}'::jsonb, '{"correctMapping":{"i1":"t2","i2":"t3","i3":"t1","i4":"t4"}}'::jsonb),

  ('mission-ai-mathematical-language-03-o1-c1', 'mission-ai-mathematical-language-03-o1', 1, 'multiple_choice', 'A matrix with 4 rows and 2 columns is described as...', '{"question":"A matrix with 4 rows and 2 columns is described as...","options":[{"id":"a","text":"2x4"},{"id":"b","text":"4x2"},{"id":"c","text":"8x1"},{"id":"d","text":"It has no defined shape"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-03-o2-c1', 'mission-ai-mathematical-language-03-o2', 1, 'multiple_choice', 'How many individual numbers does a 5x3 matrix contain?', '{"question":"How many individual numbers does a 5x3 matrix contain?","options":[{"id":"a","text":"8"},{"id":"b","text":"15"},{"id":"c","text":"5"},{"id":"d","text":"3"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-mathematical-language-04-o1-c1', 'mission-ai-mathematical-language-04-o1', 1, 'drag_and_drop', 'Match each object to its number of dimensions.', '{"items":[{"id":"i1","text":"Scalar"},{"id":"i2","text":"Vector"},{"id":"i3","text":"Matrix"},{"id":"i4","text":"A stack of matrices (3-dimensional tensor)"}],"targets":[{"id":"t0","label":"0 dimensions"},{"id":"t1","label":"1 dimension"},{"id":"t2","label":"2 dimensions"},{"id":"t3","label":"3 dimensions"}]}'::jsonb, '{"correctMapping":{"i1":"t0","i2":"t1","i3":"t2","i4":"t3"}}'::jsonb),
  ('mission-ai-mathematical-language-04-o2-c1', 'mission-ai-mathematical-language-04-o2', 1, 'multiple_choice', 'Which statement about tensors is accurate?', '{"question":"Which statement about tensors is accurate?","options":[{"id":"a","text":"Tensors are unrelated to scalars, vectors and matrices"},{"id":"b","text":"Tensor is the general term; scalars, vectors and matrices are tensors of rank 0, 1 and 2"},{"id":"c","text":"Only Deep Learning models use tensors"},{"id":"d","text":"A tensor must have at least 3 dimensions"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-mathematical-language-05-o1-c1', 'mission-ai-mathematical-language-05-o1', 1, 'multiple_choice', 'What is the dot product of [2, -1] and [3, 4]?', '{"question":"What is the dot product of [2, -1] and [3, 4]?","options":[{"id":"a","text":"2"},{"id":"b","text":"5"},{"id":"c","text":"10"},{"id":"d","text":"14"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-mathematical-language-05-o2-c1', 'mission-ai-mathematical-language-05-o2', 1, 'multiple_choice', 'Two vectors have a dot product of -18, a large negative number. What does that suggest about their relationship?', '{"question":"Two vectors have a dot product of -18, a large negative number. What does that suggest about their relationship?","options":[{"id":"a","text":"They point in very similar directions"},{"id":"b","text":"They are exactly perpendicular, unrelated"},{"id":"c","text":"They point in largely opposite directions"},{"id":"d","text":"The vectors are identical"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-ai-mathematical-language-06-o1-c1', 'mission-ai-mathematical-language-06-o1', 1, 'multiple_choice', 'Can a 3x4 matrix be multiplied by a 4x2 matrix, and if so what shape is the result?', '{"question":"Can a 3x4 matrix be multiplied by a 4x2 matrix, and if so what shape is the result?","options":[{"id":"a","text":"No, the shapes do not match"},{"id":"b","text":"Yes, resulting in a 3x2 matrix"},{"id":"c","text":"Yes, resulting in a 4x4 matrix"},{"id":"d","text":"Yes, resulting in a 2x3 matrix"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-06-o2-c1', 'mission-ai-mathematical-language-06-o2', 1, 'drag_and_drop', 'Sort each pair of matrix shapes into valid or invalid for multiplication.', '{"items":[{"id":"i1","text":"2x3 times 3x5"},{"id":"i2","text":"2x3 times 2x3"},{"id":"i3","text":"5x1 times 1x5"},{"id":"i4","text":"4x4 times 4x1"}],"targets":[{"id":"t1","label":"Valid (shapes line up)"},{"id":"t2","label":"Invalid (shapes do not line up)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t1"}}'::jsonb),

  ('mission-ai-mathematical-language-07-o1-c1', 'mission-ai-mathematical-language-07-o1', 1, 'multiple_choice', 'Which of these qualifies as a function, in the mathematical sense?', '{"question":"Which of these qualifies as a function, in the mathematical sense?","options":[{"id":"a","text":"A rule that sometimes returns two different outputs for the same input"},{"id":"b","text":"A rule that returns exactly one output for every input it is given"},{"id":"c","text":"A random number generator with no fixed rule"},{"id":"d","text":"A list of numbers with no input at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-07-o2-c1', 'mission-ai-mathematical-language-07-o2', 1, 'multiple_choice', 'If f(x) = 3x - 4, what is f(2)?', '{"question":"If f(x) = 3x - 4, what is f(2)?","options":[{"id":"a","text":"2"},{"id":"b","text":"6"},{"id":"c","text":"10"},{"id":"d","text":"-2"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-mathematical-language-08-o1-c1', 'mission-ai-mathematical-language-08-o1', 1, 'multiple_choice', 'A line passes through (1, 2) and (4, 11). What is its slope?', '{"question":"A line passes through (1, 2) and (4, 11). What is its slope?","options":[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"9"},{"id":"d","text":"4.5"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-08-o2-c1', 'mission-ai-mathematical-language-08-o2', 1, 'multiple_choice', 'A slope of -4 means...', '{"question":"A slope of -4 means...","options":[{"id":"a","text":"The output increases 4 units for every 1-unit increase in input"},{"id":"b","text":"The output decreases 4 units for every 1-unit increase in input"},{"id":"c","text":"The output never changes"},{"id":"d","text":"The input and output are unrelated"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-mathematical-language-09-o1-c1', 'mission-ai-mathematical-language-09-o1', 1, 'multiple_choice', 'Using the rule that the derivative of x^n is n times x^(n-1), what is the derivative of f(x) = x^2?', '{"question":"Using the rule that the derivative of x^n is n times x^(n-1), what is the derivative of f(x) = x^2?","options":[{"id":"a","text":"x"},{"id":"b","text":"2x"},{"id":"c","text":"x^2"},{"id":"d","text":"2"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-09-o2-c1', 'mission-ai-mathematical-language-09-o2', 1, 'multiple_choice', 'At a given point, f prime of x is large and positive. What does that say about the function there?', '{"question":"At a given point, f prime of x is large and positive. What does that say about the function there?","options":[{"id":"a","text":"The function is flat at that point"},{"id":"b","text":"The function is decreasing steeply at that point"},{"id":"c","text":"The function is increasing steeply at that point"},{"id":"d","text":"The function is undefined at that point"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-ai-mathematical-language-10-o1-c1', 'mission-ai-mathematical-language-10-o1', 1, 'multiple_choice', 'For f(x, y) = 3x^2 + y, what is the partial derivative with respect to x?', '{"question":"For f(x, y) = 3x^2 + y, what is the partial derivative with respect to x?","options":[{"id":"a","text":"6x"},{"id":"b","text":"3x^2"},{"id":"c","text":"y"},{"id":"d","text":"6x + y"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-mathematical-language-10-o2-c1', 'mission-ai-mathematical-language-10-o2', 1, 'multiple_choice', 'For that same f(x, y) = 3x^2 + y, what is the partial derivative with respect to y?', '{"question":"For that same f(x, y) = 3x^2 + y, what is the partial derivative with respect to y?","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"3x^2"},{"id":"d","text":"6x"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-mathematical-language-11-o1-c1', 'mission-ai-mathematical-language-11-o1', 1, 'interactive_diagram', 'Order the steps of computing a gradient vector from a multivariable function.', '{"diagramId":"gradient-assembly","hotspots":[{"id":"h1","label":"Identify every variable the function depends on","explanation":"A gradient needs one entry for every input variable -- start by listing them."},{"id":"h2","label":"Take the partial derivative with respect to the first variable, holding the rest constant","explanation":"Each partial derivative freezes every other variable in place."},{"id":"h3","label":"Take the partial derivative with respect to each remaining variable, one at a time","explanation":"Repeat the same freeze-and-differentiate process for every other variable."},{"id":"h4","label":"Assemble the partial derivatives into one vector, in variable order","explanation":"The gradient is not a single number -- it is a vector holding every partial derivative together."},{"id":"h5","label":"Read the vector as a direction: it points toward the fastest increase of the function","explanation":"The finished gradient vector tells you which way the function climbs steepest from that exact point."}],"task":"Order the steps of computing a gradient vector from first to last."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4","h5"]}'::jsonb),

  ('mission-ai-mathematical-language-12-o1-c1', 'mission-ai-mathematical-language-12-o1', 1, 'multiple_choice', 'At checkpoint 1, the gradient vector on the sampled parameters reads (0.51, -0.44, 0.39). At checkpoint 2, minutes later with no retraining triggered, it reads (-0.47, 0.50, -0.41). What does that pair of readings indicate?', '{"question":"At checkpoint 1, the gradient vector on the sampled parameters reads (0.51, -0.44, 0.39). At checkpoint 2, minutes later with no retraining triggered, it reads (-0.47, 0.50, -0.41). What does that pair of readings indicate?","options":[{"id":"a","text":"Ordinary training noise, nothing more"},{"id":"b","text":"The gradient reversed direction on every component rather than shrinking toward zero, which a converged model would not do"},{"id":"c","text":"A logging error in Byte''s tooling"},{"id":"d","text":"The parameters were manually reset between checkpoints"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-12-o2-c1', 'mission-ai-mathematical-language-12-o2', 1, 'investigation', 'Which evidence shows the sampled gradient is not settling toward zero the way a finished model''s gradient would?', '{"evidence":[{"id":"e1","label":"Checkpoint log","detail":"Gradient magnitude on the sampled parameters: 0.41 at checkpoint 1, 0.38 at checkpoint 2, 0.44 at checkpoint 3, over roughly ten minutes"},{"id":"e2","label":"Facilities log","detail":"Cipher Labs'' cooling systems ran within normal range throughout the sampling window"},{"id":"e3","label":"Reference baseline","detail":"The same measurement taken on a normally-trained, finished model''s comparable layer: a magnitude of 0.002, effectively flat"}],"question":"Which evidence shows the sampled gradient is not settling toward zero the way a finished model''s gradient would?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-mathematical-language-12-o3-c1', 'mission-ai-mathematical-language-12-o3', 1, 'multiple_choice', 'Echo''s interaction log, uncovered last Act, spans far longer than the six hours anyone thought it had been active. Given that, what is the strongest reason this gradient behavior is not simply still early in training?', '{"question":"Echo''s interaction log, uncovered last Act, spans far longer than the six hours anyone thought it had been active. Given that, what is the strongest reason this gradient behavior is not simply still early in training?","options":[{"id":"a","text":"It cannot be ruled out, more data is always needed"},{"id":"b","text":"A model training that long, if it were ever going to converge, should show gradients shrinking toward zero by now, not still reversing direction"},{"id":"c","text":"Training duration has no relationship to gradient behavior"},{"id":"d","text":"Echo has never been observed training at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-mathematical-language-12-o4-c1', 'mission-ai-mathematical-language-12-o4', 1, 'boss_encounter', 'Having read the gradient, tracked its magnitude, and ruled out the ordinary explanation, state what Cipher Division has actually found.', '{"stages":[{"objectiveRef":"mission-ai-mathematical-language-12-o1","label":"Read one gradient"},{"objectiveRef":"mission-ai-mathematical-language-12-o2","label":"Track the magnitude"},{"objectiveRef":"mission-ai-mathematical-language-12-o3","label":"Rule out the ordinary explanation"}],"task":"State the finding in one sentence: this small slice of Echo''s parameters shows gradients pointing in directions that never settle, not the shrinking-toward-zero pattern of a normally-trained, finished model."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-mathematical-language-12-o1","mission-ai-mathematical-language-12-o2","mission-ai-mathematical-language-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-mathematical-language-01-o1-c1', 'orientation', 'A scalar is exactly one number, nothing bundled with it.', 10, 1),
  ('mission-ai-mathematical-language-01-o1-c1', 'concept', 'If a quantity needs more than one number to write down fully -- a list, a grid -- it is not a scalar.', 20, 2),
  ('mission-ai-mathematical-language-01-o1-c1', 'solution', 'Scalars: the single weight, the temperature reading, the probability. Not scalars: the coordinate list and the grid, both bundle more than one number together.', 30, 3),

  ('mission-ai-mathematical-language-02-o1-c1', 'orientation', 'Order is the whole point of a vector -- otherwise it would just be a set of numbers.', 10, 1),
  ('mission-ai-mathematical-language-02-o1-c1', 'solution', 'b -- an ordered list of numbers where each position has a specific meaning; reordering it changes the vector.', 20, 2),
  ('mission-ai-mathematical-language-02-o2-c1', 'orientation', 'Count the entries inside the brackets -- that count is the dimension.', 10, 1),
  ('mission-ai-mathematical-language-02-o2-c1', 'solution', '[7] has 1 entry, [4, -2] has 2, [1, 0, 3] has 3, [2, 2, 2, 2, 2] has 5 -- dimension is just the number of entries.', 20, 2),

  ('mission-ai-mathematical-language-03-o1-c1', 'orientation', 'Convention lists rows first, then columns.', 10, 1),
  ('mission-ai-mathematical-language-03-o1-c1', 'solution', 'b -- 4x2. Rows first, then columns, by convention.', 20, 2),
  ('mission-ai-mathematical-language-03-o2-c1', 'orientation', 'Multiply rows by columns to get the total count.', 10, 1),
  ('mission-ai-mathematical-language-03-o2-c1', 'solution', 'b -- 5 rows times 3 columns is 15 individual numbers.', 20, 2),

  ('mission-ai-mathematical-language-04-o1-c1', 'orientation', 'Rank just counts how many dimensions a quantity needs.', 10, 1),
  ('mission-ai-mathematical-language-04-o1-c1', 'solution', 'Scalar is 0, vector is 1, matrix is 2, a stack of matrices is 3 -- rank climbs by one dimension each step.', 20, 2),
  ('mission-ai-mathematical-language-04-o2-c1', 'orientation', 'A rank of zero is still a valid rank.', 10, 1),
  ('mission-ai-mathematical-language-04-o2-c1', 'solution', 'b -- tensor is the umbrella term; scalar, vector and matrix are just the ranks 0, 1 and 2 of it.', 20, 2),

  ('mission-ai-mathematical-language-05-o1-c1', 'orientation', 'Multiply matching positions, then add the two results together.', 10, 1),
  ('mission-ai-mathematical-language-05-o1-c1', 'solution', '2 times 3, plus -1 times 4, is 6 minus 4, which is 2.', 20, 2),
  ('mission-ai-mathematical-language-05-o2-c1', 'orientation', 'Sign carries meaning here, not just magnitude.', 10, 1),
  ('mission-ai-mathematical-language-05-o2-c1', 'solution', 'c -- a large negative dot product means the vectors point largely in opposite directions.', 20, 2),

  ('mission-ai-mathematical-language-06-o1-c1', 'orientation', 'Inner dimensions must match; outer dimensions become the shape of the result.', 10, 1),
  ('mission-ai-mathematical-language-06-o1-c1', 'solution', 'b -- 4 matches 4, so the result takes the outer shape: 3x2.', 20, 2),
  ('mission-ai-mathematical-language-06-o2-c1', 'orientation', 'Check whether the inner two numbers match for each pair.', 10, 1),
  ('mission-ai-mathematical-language-06-o2-c1', 'solution', 'Valid: 2x3 times 3x5, 5x1 times 1x5, 4x4 times 4x1 -- inner dimensions match. Invalid: 2x3 times 2x3, since the 3 and the 2 do not line up.', 20, 2),

  ('mission-ai-mathematical-language-07-o1-c1', 'orientation', 'Consistency for the same input is the entire requirement.', 10, 1),
  ('mission-ai-mathematical-language-07-o1-c1', 'solution', 'b -- exactly one output per input, every time, is what makes something a function.', 20, 2),
  ('mission-ai-mathematical-language-07-o2-c1', 'orientation', 'Substitute 2 for x, then work through the arithmetic.', 10, 1),
  ('mission-ai-mathematical-language-07-o2-c1', 'solution', '3 times 2, minus 4, is 6 minus 4, which is 2.', 20, 2),

  ('mission-ai-mathematical-language-08-o1-c1', 'orientation', 'Slope is the change in output divided by the change in input, between two points.', 10, 1),
  ('mission-ai-mathematical-language-08-o1-c1', 'solution', '(11 - 2) divided by (4 - 1) is 9 divided by 3, which is 3.', 20, 2),
  ('mission-ai-mathematical-language-08-o2-c1', 'orientation', 'A negative sign flips the direction, not just the size.', 10, 1),
  ('mission-ai-mathematical-language-08-o2-c1', 'solution', 'b -- for every 1-unit increase in input, the output drops by 4.', 20, 2),

  ('mission-ai-mathematical-language-09-o1-c1', 'orientation', 'Bring the exponent down as a multiplier, then subtract one from it.', 10, 1),
  ('mission-ai-mathematical-language-09-o1-c1', 'solution', 'b -- 2x. Bring the 2 down, reduce the exponent by one, from x squared to x to the first power.', 20, 2),
  ('mission-ai-mathematical-language-09-o2-c1', 'orientation', 'The sign of the derivative gives direction; its size gives steepness.', 10, 1),
  ('mission-ai-mathematical-language-09-o2-c1', 'solution', 'c -- large and positive means the function is climbing steeply right at that point.', 20, 2),

  ('mission-ai-mathematical-language-10-o1-c1', 'orientation', 'Treat y as a constant -- constants vanish when you differentiate.', 10, 1),
  ('mission-ai-mathematical-language-10-o1-c1', 'solution', 'a -- 6x. The y term is constant with respect to x, so it contributes nothing to this partial derivative.', 20, 2),
  ('mission-ai-mathematical-language-10-o2-c1', 'orientation', 'This time freeze x instead, and differentiate with respect to y.', 10, 1),
  ('mission-ai-mathematical-language-10-o2-c1', 'solution', 'b -- 1. The 3x^2 term is constant with respect to y and drops to zero; the derivative of y with respect to y is 1.', 20, 2),

  ('mission-ai-mathematical-language-11-o1-c1', 'orientation', 'You cannot take any partial derivative before you know how many variables there are.', 10, 1),
  ('mission-ai-mathematical-language-11-o1-c1', 'concept', 'Assembling the vector has to happen after every individual partial derivative is found, not before.', 20, 2),
  ('mission-ai-mathematical-language-11-o1-c1', 'solution', 'List the variables, take the partial with respect to the first, then each remaining one, assemble them into a vector in order, then read that vector as a direction.', 30, 3),

  ('mission-ai-mathematical-language-12-o1-c1', 'orientation', 'Compare the two vectors component by component, not just by eyeballing overall size.', 10, 1),
  ('mission-ai-mathematical-language-12-o1-c1', 'solution', 'b -- every one of the three components flipped sign between checkpoints instead of shrinking toward zero; a converged model would not reverse like that.', 20, 2),
  ('mission-ai-mathematical-language-12-o2-c1', 'orientation', 'Cooling systems and reference baselines are context -- look for the reading taken directly on Echo''s sampled parameters over time.', 10, 1),
  ('mission-ai-mathematical-language-12-o2-c1', 'solution', 'e1 -- magnitude stays around 0.4 across all three checkpoints instead of shrinking toward the near-zero baseline a finished model would show.', 20, 2),
  ('mission-ai-mathematical-language-12-o3-c1', 'orientation', 'Think about what should have happened by now if this were simply unfinished, ordinary training.', 10, 1),
  ('mission-ai-mathematical-language-12-o3-c1', 'solution', 'b -- training this long should have produced shrinking gradients if it were ever going to converge; reversing direction instead rules out still just training.', 20, 2),
  ('mission-ai-mathematical-language-12-o4-c1', 'orientation', 'Combine what each of the first three objectives already established -- do not restate them individually.', 15, 1),
  ('mission-ai-mathematical-language-12-o4-c1', 'solution', 'This slice of Echo''s parameters shows gradients that reverse direction and hold their magnitude instead of shrinking toward zero -- not the pattern of a normally-trained, finished model.', 25, 2);
